import pandas as pd
import math

def delivery_report(raw):
    t = raw.loc[raw['actual_min'].between(1,299)].copy()
    if t.empty:
        return dict(late_pct=None, worst_courier=None, worst_shop=None, peak_hours=[], fair_promise=None)
    t['late'] = t['actual_min'] > t['promised_min']
    t['hour'] = t['created'].dt.hour
    hours = t.groupby('hour')['late'].agg(['mean','size'])
    peak = hours.index[(hours['mean'] > .25) & (hours['size'] >= 50)].tolist()
    walk = t.loc[(t['courier'] == 'пеший') & (t['promised_min']==30),'actual_min']
    if walk.empty:
        fair = None
        print('Нет пеших с обещанием 30 минут; обещание рассчитать нельзя')
    else:
        fair = math.ceil(walk.quantile(.8)/5)*5
    return dict(late_pct=round(t['late'].mean()*100,1), worst_courier=t.groupby('courier')['late'].mean().idxmax(), worst_shop=t.groupby('shop_id')['late'].mean().idxmax(), peak_hours=sorted(peak), fair_promise=fair)

